package com.bank.fee;

import java.math.BigDecimal;
import java.util.logging.*;

public class TriFunctionDemo {
    private static final Logger log = Logger.getLogger("Fee");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        FeeService service = new FeeService();

        // implement the 3-arg SAM with a lambda
        TriFunction<BigDecimal, BigDecimal, Integer, BigDecimal> simpleInterest =
            (principal, ratePct, years) -> principal
                .multiply(ratePct).movePointLeft(2)
                .multiply(BigDecimal.valueOf(years));

        BigDecimal interest = service.compute(simpleInterest,
            new BigDecimal("1000000"), new BigDecimal("8"), 3);
        log.info(() -> "Simple interest = " + interest);  // 1,000,000 × 8% × 3
    }
}

// ─── File: src/main/java/com/bank/fee/TriFunction.java ───
@FunctionalInterface
interface TriFunction<A, B, C, R> {
    R apply(A a, B b, C c);   // single abstract method, 3 inputs
}

// ─── Would be in service/FeeService.java ───
class FeeService {
    <A, B, C, R> R compute(TriFunction<A, B, C, R> fn, A a, B b, C c) {
        return fn.apply(a, b, c);
    }
}
